def run(task, budget):
    state = start(task)
    seen = Counter()
    while True:
        if state.steps >= budget.max_steps:    return stop('max_steps', state)
        if state.tokens >= budget.max_tokens:  return stop('max_tokens', state)
        if clock() - state.t0 >= budget.max_s: return stop('deadline', state)
        step = model.next_step(state.context)
        if step.final:                         return finish(step, state)
        key = (step.tool, canonical(step.args))
        seen[key] += 1
        if seen[key] > budget.max_repeat:      return stop('repeated_call', state)
        obs = call_tool(step, idempotency_key=state.key(step))
        state = state.append(step, trim(obs))
